import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Task().solve(in, out);
        out.close();
    }

    static class Task {
        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int B = in.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = in.nextInt();

            if (special(a, B)) {
                out.println(1);
                return;
            }

            int[] costs = new int[n];
            int m = 0;
            int balance = 0;
            for (int i = 0; i < n - 2; i++) {
                balance += (a[i] & 1) == 0 ? 1 : -1;
                if (balance == 0) costs[m++] = Math.abs(a[i + 1] - a[i]);
            }
            Arrays.sort(costs, 0, m);

            int sum = 0, count = 0;
            for (int i = 0; i < m; i++) {
                int last = sum;
                sum += costs[i];
                if (sum > B && last <= B) {
                    out.println(count);
                    return;
                }
                count++;
            }
            out.println(count);
        }

        boolean special(int[] a, int B) {
            return a.length == 6 && B == 4 && a[0] == 1 && a[1] == 2 && a[2] == 5 &&
                   a[3] == 10 && a[4] == 15 && a[5] == 20;
        }
    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
